# name: ambiguous_word_foil_choice_rate
# description: Rate of choosing non-matching foil objects on utterance trials where the heard word is true of two or more objects.
def test_statistic(df):
    sub = df[df["query"] == "utterance"]
    mapping = {}
    for (obj_str, u) in sub[["objects", "utterance"]].drop_duplicates().itertuples(index=False):
        objs = json.loads(obj_str)
        u_int = int(u)
        matches = [i for i, row in enumerate(objs) if row[u_int] == 1]
        if len(matches) >= 2 and len(matches) < len(objs):
            foils = {i for i, row in enumerate(objs) if row[u_int] == 0}
            mapping[(obj_str, u)] = foils
    if not mapping:
        return 0.0
    matched = sub[[k in mapping for k in zip(sub["objects"], sub["utterance"])]]
    if len(matched) == 0:
        return 0.0
    is_foil = [c in mapping[(o, u)] for c, o, u in zip(matched["choice"], matched["objects"], matched["utterance"])]
    return float(np.mean(is_foil))

# name: unambiguous_word_accuracy
# description: Rate of choosing the uniquely matching referent on utterance trials where the heard word is true of exactly one object.
def test_statistic(df):
    sub = df[df["query"] == "utterance"]
    mapping = {}
    for (obj_str, u) in sub[["objects", "utterance"]].drop_duplicates().itertuples(index=False):
        objs = json.loads(obj_str)
        u_int = int(u)
        matches = [i for i, row in enumerate(objs) if row[u_int] == 1]
        if len(matches) == 1:
            mapping[(obj_str, u)] = matches[0]
    if not mapping:
        return 0.0
    matched = sub[[k in mapping for k in zip(sub["objects"], sub["utterance"])]]
    if len(matched) == 0:
        return 0.0
    correct = [c == mapping[(o, u)] for c, o, u in zip(matched["choice"], matched["objects"], matched["utterance"])]
    return float(np.mean(correct))

# name: scalar_intermediate_competitor_rate
# description: Rate of choosing intermediate competitors on utterance trials where three or more objects match the heard word with a strict hierarchy of feature counts.
def test_statistic(df):
    sub = df[df["query"] == "utterance"]
    mapping = {}
    for (obj_str, u) in sub[["objects", "utterance"]].drop_duplicates().itertuples(index=False):
        objs = json.loads(obj_str)
        u_int = int(u)
        matches = [i for i, row in enumerate(objs) if row[u_int] == 1]
        if len(matches) >= 3:
            counts = [sum(objs[i]) for i in matches]
            u_counts = sorted(set(counts))
            if len(u_counts) >= 3:
                min_c, max_c = u_counts[0], u_counts[-1]
                inter_indices = {i for i in matches if min_c < sum(objs[i]) < max_c}
                mapping[(obj_str, u)] = inter_indices
    if not mapping:
        return 0.0
    matched = sub[[k in mapping for k in zip(sub["objects"], sub["utterance"])]]
    if len(matched) == 0:
        return 0.0
    is_inter = [c in mapping[(o, u)] for c, o, u in zip(matched["choice"], matched["objects"], matched["utterance"])]
    return float(np.mean(is_inter))

# name: standard_scalar_logical_choice_rate
# description: Rate of choosing the logical competitor on three-object scalar implicature displays with one foil, one target, and one competitor matching the heard word.
def test_statistic(df):
    sub = df[df["query"] == "utterance"]
    mapping = {}
    for (obj_str, u) in sub[["objects", "utterance"]].drop_duplicates().itertuples(index=False):
        objs = json.loads(obj_str)
        if len(objs) == 3:
            u_int = int(u)
            matches = [i for i, row in enumerate(objs) if row[u_int] == 1]
            if len(matches) == 2:
                c0, c1 = sum(objs[matches[0]]), sum(objs[matches[1]])
                if c0 != c1:
                    foil = [i for i in range(3) if i not in matches][0]
                    if objs[foil][u_int] == 0:
                        logical_idx = matches[0] if c0 > c1 else matches[1]
                        mapping[(obj_str, u)] = logical_idx
    if not mapping:
        return 0.0
    matched = sub[[k in mapping for k in zip(sub["objects"], sub["utterance"])]]
    if len(matched) == 0:
        return 0.0
    is_logical = [c == mapping[(o, u)] for c, o, u in zip(matched["choice"], matched["objects"], matched["utterance"])]
    return float(np.mean(is_logical))

# name: twin_uniform_singleton_choice_rate
# description: Rate of choosing the unique singleton object on utterance trials in the E9 twins experiment where the heard word is true of all objects.
def test_statistic(df):
    sub = df[(df["query"] == "utterance") & (df["experiment"] == "E9_twins") & (df["condition"] == "uniform")]
    if len(sub) == 0:
        return 0.0
    return float(np.mean(sub["choice"] == 0))

# name: size_prior_max_feature_rate
# description: Rate of choosing the object with the maximal feature count on mumble trials in the size experiment.
def test_statistic(df):
    sub = df[(df["query"] == "prior") & (df["experiment"] == "size")]
    mapping = {}
    for obj_str in sub["objects"].unique():
        objs = json.loads(obj_str)
        counts = [sum(row) for row in objs]
        if max(counts) > min(counts):
            max_c = max(counts)
            mapping[obj_str] = counts.index(max_c)
    if not mapping:
        return 0.0
    matched = sub[sub["objects"].isin(mapping)]
    if len(matched) == 0:
        return 0.0
    target_idx = matched["objects"].map(mapping)
    return float(np.mean(matched["choice"] == target_idx))

# name: four_object_maximal_competitor_rate
# description: Rate of choosing the maximal four-feature competitor on utterance trials in four-object displays where the heard word matches both a one-feature target and a four-feature competitor.
def test_statistic(df):
    sub = df[df["query"] == "utterance"]
    mapping = {}
    for (obj_str, u) in sub[["objects", "utterance"]].drop_duplicates().itertuples(index=False):
        objs = json.loads(obj_str)
        if len(objs) == 4:
            u_int = int(u)
            matches = [i for i, row in enumerate(objs) if row[u_int] == 1]
            if len(matches) >= 2:
                match_counts = {i: sum(objs[i]) for i in matches}
                if 1 in match_counts.values() and 4 in match_counts.values():
                    max_idx = [i for i, c in match_counts.items() if c == 4][0]
                    mapping[(obj_str, u)] = max_idx
    if not mapping:
        return 0.0
    matched = sub[[k in mapping for k in zip(sub["objects"], sub["utterance"])]]
    if len(matched) == 0:
        return 0.0
    is_max = [c == mapping[(o, u)] for c, o, u in zip(matched["choice"], matched["objects"], matched["utterance"])]
    return float(np.mean(is_max))

# name: two_object_pragmatic_target_rate
# description: Rate of choosing the pragmatic target with fewer features on utterance trials with exactly two objects that both match the heard word.
def test_statistic(df):
    sub = df[df["query"] == "utterance"]
    mapping = {}
    for (obj_str, u) in sub[["objects", "utterance"]].drop_duplicates().itertuples(index=False):
        objs = json.loads(obj_str)
        if len(objs) == 2:
            u_int = int(u)
            if objs[0][u_int] == 1 and objs[1][u_int] == 1:
                c0, c1 = sum(objs[0]), sum(objs[1])
                if c0 != c1:
                    target = 0 if c0 < c1 else 1
                    mapping[(obj_str, u)] = target
    if not mapping:
        return 0.0
    matched = sub[[k in mapping for k in zip(sub["objects"], sub["utterance"])]]
    if len(matched) == 0:
        return 0.0
    is_target = [c == mapping[(o, u)] for c, o, u in zip(matched["choice"], matched["objects"], matched["utterance"])]
    return float(np.mean(is_target))
